import { describe, expect, it } from 'vitest';
import fixture from '@mahoshojo/contracts/fixtures/arena-room-proposal-reconciliation.json';
import {
  createArenaRoomProposalReconciliationTarget as createTarget,
  observeArenaRoomProposalReconciliation as observe,
  type ArenaRoomProposalReconciliationInput,
  type ArenaRoomProposalReconciliationEvidence,
} from '../src';

// This same fixture is consumed by arena_room_proposal.rs at the Native boundary.
// Expected observations are explicit business assertions, not generated by either implementation.
const targets = fixture.targets as unknown as Record<string, ArenaRoomProposalReconciliationInput>;

describe('proposal reconciliation shared TypeScript/Native golden cases', () => {
  it.each(fixture.cases)('$name', ({ target: name, steps }) => {
    const target = createTarget(targets[name]);
    let linked = target.linked;
    for (const step of steps) {
      const evidence = step.evidence as ArenaRoomProposalReconciliationEvidence;
      const before = structuredClone({ target, evidence });
      const actual = observe(target, evidence, linked);
      expect(actual).toEqual(step.expected);
      expect({ target, evidence }).toEqual(before);
      linked = actual.linked;
    }
  });
});
